// File: p2p-kids-marketplace/src/hooks/__tests__/usePaymentSheet.test.ts
// MODULE-11 SUB-015: Unit tests for usePaymentSheet hook

import { renderHook, act } from '@testing-library/react-native';
import { usePaymentSheet } from '../usePaymentSheet';
import * as StripeReactNative from '@stripe/stripe-react-native';
import { supabase } from '../../config/supabase';

// Mock Stripe
jest.mock('@stripe/stripe-react-native', () => ({
  useStripe: jest.fn(),
  initStripe: jest.fn(),
  initPaymentSheet: jest.fn(),
  presentPaymentSheet: jest.fn(),
}));

// Mock supabase
jest.mock('../../config/supabase', () => {
  const mockSupabaseInstance = {
    auth: {
      getSession: jest.fn(),
    },
    functions: {
      invoke: jest.fn(),
    },
  };

  return {
    supabase: mockSupabaseInstance,
  };
});

describe('usePaymentSheet', () => {
  const mockSession = {
    access_token: 'test_token',
    user: { id: 'test_user_id', email: 'test@example.com' },
  };

  const mockSetupIntentResponse = {
    client_secret: 'seti_test_secret',
    publishable_key: 'pk_test_123',
    ephemeral_key_secret: 'ek_test_secret',
    customer_id: 'cus_test_123',
  };

  beforeEach(() => {
    jest.clearAllMocks();

    (StripeReactNative.useStripe as jest.Mock).mockReturnValue({
      retrieveSetupIntent: jest.fn().mockResolvedValue({
        setupIntent: { paymentMethodId: 'pm_test_123' },
        error: null,
      }),
    });

    // Mock supabase session
    (supabase.auth.getSession as jest.Mock).mockResolvedValue({
      data: { session: mockSession },
      error: null,
    });

    (StripeReactNative.initStripe as jest.Mock).mockResolvedValue({});

    (supabase.functions.invoke as jest.Mock).mockResolvedValue({
      data: mockSetupIntentResponse,
      error: null,
    });

    // Mock Stripe functions
    (StripeReactNative.initPaymentSheet as jest.Mock).mockResolvedValue({
      error: null,
    });

    (StripeReactNative.presentPaymentSheet as jest.Mock).mockResolvedValue({
      error: null,
    });
  });

  describe('setupPaymentSheet', () => {
    it('should initialize payment sheet successfully', async () => {
      const { result } = renderHook(() => usePaymentSheet());

      expect(result.current.loading).toBe(false);
      expect(result.current.error).toBeNull();

      await act(async () => {
        await result.current.setupPaymentSheet({
          amount: 499,
          isRenewal: false,
        });
      });

      // Should call create-payment-setup-intent Edge Function
      expect(supabase.functions.invoke).toHaveBeenCalledWith(
        'create-payment-setup-intent',
        expect.objectContaining({
          body: expect.objectContaining({
            user_id: mockSession.user.id,
            for_renewal: false,
          }),
          headers: expect.objectContaining({
            Authorization: `Bearer ${mockSession.access_token}`,
          }),
        })
      );

      // Should initialize Stripe Payment Sheet
      expect(StripeReactNative.initPaymentSheet).toHaveBeenCalledWith(
        expect.objectContaining({
          merchantDisplayName: 'Kids P2P Marketplace',
          customerId: mockSetupIntentResponse.customer_id,
          setupIntentClientSecret: mockSetupIntentResponse.client_secret,
        })
      );

      expect(result.current.error).toBeNull();
    });

    it('should handle API error gracefully', async () => {
      (supabase.functions.invoke as jest.Mock).mockResolvedValueOnce({
        data: null,
        error: { message: 'API error' },
      });

      const { result } = renderHook(() => usePaymentSheet());

      await expect(
        act(async () => {
          await result.current.setupPaymentSheet({
            amount: 499,
            isRenewal: false,
          });
        })
      ).rejects.toThrow('API error');
    });

    it('should handle Stripe initialization error', async () => {
      (StripeReactNative.initPaymentSheet as jest.Mock).mockResolvedValueOnce({
        error: { message: 'Stripe initialization failed' },
      });

      const { result } = renderHook(() => usePaymentSheet());

      await expect(
        act(async () => {
          await result.current.setupPaymentSheet({
            amount: 499,
            isRenewal: false,
          });
        })
      ).rejects.toThrow('Stripe initialization failed');
    });

    it('should handle missing authentication', async () => {
      (supabase.auth.getSession as jest.Mock).mockResolvedValueOnce({
        data: { session: null },
        error: null,
      });

      const { result } = renderHook(() => usePaymentSheet());

      await expect(
        act(async () => {
          await result.current.setupPaymentSheet({
            amount: 499,
            isRenewal: false,
          });
        })
      ).rejects.toThrow('Not authenticated');
    });
  });

  describe('presentSheet', () => {
    it('should present payment sheet successfully', async () => {
      const { result } = renderHook(() => usePaymentSheet());

      // Setup first
      await act(async () => {
        await result.current.setupPaymentSheet({
          amount: 499,
          isRenewal: false,
        });
      });

      // Present
      let presentResult;
      await act(async () => {
        presentResult = await result.current.presentSheet();
      });

      expect(StripeReactNative.presentPaymentSheet).toHaveBeenCalled();
      expect(presentResult).toEqual({
        success: true,
        paymentMethodId: expect.any(String),
      });
    });

    it('should handle user cancellation', async () => {
      (StripeReactNative.presentPaymentSheet as jest.Mock).mockResolvedValueOnce({
        error: { code: 'Canceled', message: 'User cancelled' },
      });

      const { result } = renderHook(() => usePaymentSheet());

      // Setup first
      await act(async () => {
        await result.current.setupPaymentSheet({
          amount: 499,
          isRenewal: false,
        });
      });

      // Present
      let presentResult;
      await act(async () => {
        presentResult = await result.current.presentSheet();
      });

      expect(presentResult).toEqual({
        success: false,
        error: 'Payment cancelled',
      });
    });

    it('should fail if not initialized', async () => {
      const { result } = renderHook(() => usePaymentSheet());

      let presentResult;
      await act(async () => {
        presentResult = await result.current.presentSheet();
      });

      expect(presentResult).toEqual({
        success: false,
        error: 'Payment sheet not initialized. Call setupPaymentSheet first.',
      });
      expect(result.current.error).toBe('Payment sheet not initialized. Call setupPaymentSheet first.');
    });
  });

  describe('resetError', () => {
    it('should clear error state', async () => {
      (supabase.functions.invoke as jest.Mock).mockResolvedValueOnce({
        data: null,
        error: { message: 'Test error' },
      });

      const { result } = renderHook(() => usePaymentSheet());

      // Trigger error
      await act(async () => {
        try {
          await result.current.setupPaymentSheet({
            amount: 499,
            isRenewal: false,
          });
        } catch {
          // Expected
        }
      });

      expect(result.current.error).toBe('Test error');

      // Reset error
      act(() => {
        result.current.resetError();
      });

      expect(result.current.error).toBeNull();
    });
  });
});

// File: p2p-kids-marketplace/src/components/subscription/__tests__/SubscribeButton.test.tsx
// MODULE-11 SUB-015: Unit tests for SubscribeButton component

import React from 'react';
import { render, fireEvent, waitFor } from '@testing-library/react-native';
import { Alert } from 'react-native';
import { SubscribeButton } from '../SubscribeButton';
import { usePaymentSheet } from '../../../hooks/usePaymentSheet';
import { supabase } from '../../../config/supabase';

// Mock navigation
const mockNavigate = jest.fn();
jest.mock('@react-navigation/native', () => ({
  ...jest.requireActual('@react-navigation/native'),
  useNavigation: () => ({
    navigate: mockNavigate,
  }),
}));

// Mock usePaymentSheet
jest.mock('../../../hooks/usePaymentSheet', () => ({
  usePaymentSheet: jest.fn(),
}));

// Mock supabase
jest.mock('../../../config/supabase', () => ({
  supabase: {
    auth: {
      getSession: jest.fn(),
    },
    functions: {
      invoke: jest.fn(),
    },
  },
}));

// Mock Alert
jest.spyOn(Alert, 'alert');

describe('SubscribeButton', () => {
  const mockSession = {
    access_token: 'test_token',
    user: { id: 'test_user_id' },
  };

  const mockPaymentSheet = {
    setupPaymentSheet: jest.fn(),
    presentSheet: jest.fn(),
    loading: false,
    error: null,
    resetError: jest.fn(),
  };

  beforeEach(() => {
    jest.clearAllMocks();

    (usePaymentSheet as jest.Mock).mockReturnValue(mockPaymentSheet);

    (supabase.auth.getSession as jest.Mock).mockResolvedValue({
      data: { session: mockSession },
      error: null,
    });
  });

  describe('Initial render', () => {
    it('should render subscribe button with default label', () => {
      const { getByTestId } = render(<SubscribeButton priceCents={499} />);

      const button = getByTestId('subscribe-button');
      const label = getByTestId('subscribe-button-label');

      expect(button).toBeTruthy();
      expect(label.props.children).toBe('Subscribe to Kids Club+');
    });

    it('should render re-subscribe label when isRenewal=true', () => {
      const { getByTestId } = render(<SubscribeButton isRenewal priceCents={499} />);

      const label = getByTestId('subscribe-button-label');
      expect(label.props.children).toBe('Re-subscribe Now');
    });

    it('should render custom label', () => {
      const { getByTestId } = render(<SubscribeButton label="Custom Label" priceCents={499} />);

      const label = getByTestId('subscribe-button-label');
      expect(label.props.children).toBe('Custom Label');
    });

    it('should display trial disclaimer for new subscription', () => {
      const { getByTestId } = render(<SubscribeButton priceCents={499} />);

      const disclaimer = getByTestId('subscribe-button-disclaimer');
      expect(disclaimer.props.children).toContain('30-day free trial');
    });

    it('should display renewal disclaimer for re-subscription', () => {
      const { getByTestId } = render(<SubscribeButton isRenewal priceCents={499} />);

      const disclaimer = getByTestId('subscribe-button-disclaimer');
      expect(disclaimer.props.children).toContain('Your card will be charged');
    });
  });

  describe('Subscribe flow', () => {
    it('should handle successful subscription', async () => {
      mockPaymentSheet.presentSheet.mockResolvedValueOnce({
        success: true,
        paymentMethodId: 'pm_test_123',
      });

      (supabase.functions.invoke as jest.Mock).mockResolvedValueOnce({
        data: {
          subscription_id: 'sub_test_123',
          status: 'active',
          current_period_end: '2024-04-01T00:00:00Z',
        },
        error: null,
      });

      const { getByTestId } = render(<SubscribeButton priceCents={499} />);

      const button = getByTestId('subscribe-button');
      fireEvent.press(button);

      await waitFor(() => {
        expect(mockPaymentSheet.setupPaymentSheet).toHaveBeenCalledWith({
          amount: 499,
          isRenewal: false,
        });
      });

      await waitFor(() => {
        expect(mockPaymentSheet.presentSheet).toHaveBeenCalled();
      });

      await waitFor(() => {
        expect(supabase.functions.invoke).toHaveBeenCalledWith(
          'create-subscription-from-payment-method',
          expect.objectContaining({
            body: expect.objectContaining({
              payment_method_id: 'pm_test_123',
            }),
          })
        );
      });

      await waitFor(() => {
        expect(Alert.alert).toHaveBeenCalledWith(
          'Success!',
          expect.stringContaining('30-day free trial'),
          expect.any(Array)
        );
      });
    });

    it('should handle user cancellation gracefully', async () => {
      mockPaymentSheet.presentSheet.mockResolvedValueOnce({
        success: false,
        error: 'Payment cancelled',
      });

      const { getByTestId } = render(<SubscribeButton priceCents={499} />);

      const button = getByTestId('subscribe-button');
      fireEvent.press(button);

      await waitFor(() => {
        expect(mockPaymentSheet.presentSheet).toHaveBeenCalled();
      });

      // Should not show error for cancellation
      expect(Alert.alert).not.toHaveBeenCalled();
    });

    it('should handle payment error', async () => {
      mockPaymentSheet.presentSheet.mockResolvedValueOnce({
        success: false,
        error: 'Card declined',
      });

      const { getByTestId } = render(<SubscribeButton priceCents={499} />);

      const button = getByTestId('subscribe-button');
      fireEvent.press(button);

      await waitFor(() => {
        expect(Alert.alert).toHaveBeenCalledWith(
          'Payment Error',
          expect.stringContaining('Card declined'),
          expect.any(Array)
        );
      });
    });

    it('should handle subscription creation error', async () => {
      mockPaymentSheet.presentSheet.mockResolvedValueOnce({
        success: true,
        paymentMethodId: 'pm_test_123',
      });

      (supabase.functions.invoke as jest.Mock).mockResolvedValueOnce({
        data: null,
        error: { message: 'Subscription creation failed' },
      });

      const { getByTestId } = render(<SubscribeButton priceCents={499} />);

      const button = getByTestId('subscribe-button');
      fireEvent.press(button);

      await waitFor(() => {
        expect(Alert.alert).toHaveBeenCalledWith(
          'Payment Error',
          expect.stringContaining('Subscription creation failed'),
          expect.any(Array)
        );
      });
    });

    it('should call onSuccess callback', async () => {
      const onSuccess = jest.fn();

      mockPaymentSheet.presentSheet.mockResolvedValueOnce({
        success: true,
        paymentMethodId: 'pm_test_123',
      });

      (supabase.functions.invoke as jest.Mock).mockResolvedValueOnce({
        data: {
          subscription_id: 'sub_test_123',
          status: 'active',
        },
        error: null,
      });

      const { getByTestId } = render(<SubscribeButton onSuccess={onSuccess} priceCents={499} />);

      const button = getByTestId('subscribe-button');
      fireEvent.press(button);

      await waitFor(() => {
        expect(Alert.alert).toHaveBeenCalled();
      });

      // Simulate pressing OK on alert
      const alertCalls = (Alert.alert as jest.Mock).mock.calls;
      const okButton = alertCalls[0][2][0]; // First alert, third arg (buttons), first button
      expect(typeof okButton.onPress).toBe('function');
      okButton.onPress();

      expect(onSuccess).toHaveBeenCalled();
    });
  });

  describe('Loading state', () => {
    it('should show loading indicator when processing', () => {
      (usePaymentSheet as jest.Mock).mockReturnValue({
        ...mockPaymentSheet,
        loading: true,
      });

      const { getByTestId, queryByTestId } = render(<SubscribeButton priceCents={499} />);

      const loadingIndicator = getByTestId('subscribe-button-loading');
      const label = queryByTestId('subscribe-button-label');

      expect(loadingIndicator).toBeTruthy();
      expect(label).toBeNull();
    });

    it('should disable button when loading', () => {
      (usePaymentSheet as jest.Mock).mockReturnValue({
        ...mockPaymentSheet,
        loading: true,
      });

      const { getByTestId } = render(<SubscribeButton priceCents={499} />);

      const button = getByTestId('subscribe-button');

      // Button should be disabled
      expect(button.props.accessibilityState?.disabled).toBe(true);
    });
  });

  describe('Error display', () => {
    it('should show error message when error exists', () => {
      (usePaymentSheet as jest.Mock).mockReturnValue({
        ...mockPaymentSheet,
        error: 'Test error message',
      });

      const { getByTestId } = render(<SubscribeButton priceCents={499} />);

      const error = getByTestId('subscribe-button-error');
      expect(error.props.children).toBe('Test error message');
    });

    it('should reset error when button pressed', async () => {
      const { getByTestId } = render(<SubscribeButton priceCents={499} />);

      const button = getByTestId('subscribe-button');
      fireEvent.press(button);

      await waitFor(() => {
        expect(mockPaymentSheet.resetError).toHaveBeenCalled();
      });
    });
  });
});

/**
 * File: p2p-kids-marketplace/src/services/subscriptionNotifications.ts
 * MODULE-14 TASK NOTIF-V2-002: Subscription Event Notifications
 * 
 * Service for sending subscription lifecycle notifications
 * Integrates with existing notification infrastructure
 */

import { supabase } from '../config/supabase';

export interface SubscriptionNotificationOptions {
  userId: string;
  title: string;
  body: string;
  data?: Record<string, any>;
  critical?: boolean; // If true, ignores user preferences
}

/**
 * Send a subscription-related notification
 * Respects user notification preferences unless marked critical
 * 
 * @param options - Notification options
 * @returns Success status
 */
export async function sendSubscriptionNotification(
  options: SubscriptionNotificationOptions
): Promise<{ success: boolean; error?: string }> {
  const { userId, title, body, data = {}, critical = false } = options;

  try {
    // Get user notification preferences
    const { data: preferences, error: prefError } = await supabase
      .from('notification_preferences')
      .select('push_enabled, in_app_enabled, email_enabled')
      .eq('user_id', userId)
      .eq('category', 'subscription')
      .maybeSingle();

    if (prefError) {
      console.error('[subscriptionNotifications] Failed to fetch preferences:', prefError);
      // Continue anyway - use default preferences
    }

    // Determine channels based on preferences or critical flag
    const channels: string[] = [];

    if (critical) {
      // Critical notifications bypass preferences
      channels.push('push', 'in_app', 'email');
    } else {
      // Respect user preferences
      if (preferences?.push_enabled !== false) {
        channels.push('push');
      }
      if (preferences?.in_app_enabled !== false) {
        channels.push('in_app');
      }
      if (preferences?.email_enabled === true) {
        channels.push('email');
      }
    }

    // Create notification in database
    const { error: insertError } = await supabase
      .from('user_notifications')
      .insert({
        user_id: userId,
        type: 'subscription',
        title,
        body,
        data: {
          ...data,
          critical: critical || undefined,
        },
        is_read: false,
        created_at: new Date().toISOString(),
      });

    if (insertError) {
      console.error('[subscriptionNotifications] Failed to create notification:', insertError);
      return { success: false, error: insertError.message };
    }

    // Send push notification if enabled
    if (channels.includes('push')) {
      const { error: pushError } = await supabase.functions.invoke('send-push-notification', {
        body: {
          user_id: userId,
          title,
          body,
          data: {
            ...data,
            type: 'subscription',
            critical: critical || undefined,
          },
        },
      });

      if (pushError) {
        console.warn('[subscriptionNotifications] Push notification failed:', pushError);
        // Don't fail the whole operation if push fails
      }
    }

    return { success: true };
  } catch (err) {
    const error = err as Error;
    console.error('[subscriptionNotifications] Error:', error);
    return { success: false, error: error.message };
  }
}

/**
 * Send subscription renewal success notification
 * 
 * @param userId - User ID
 * @param nextBillingDate - Next billing date
 */
export async function notifySubscriptionRenewed(
  userId: string,
  nextBillingDate: string
): Promise<{ success: boolean; error?: string }> {
  const formattedDate = new Date(nextBillingDate).toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'long',
    day: 'numeric',
  });

  return sendSubscriptionNotification({
    userId,
    title: 'Subscription Renewed ✅',
    body: `Your Kids Club+ subscription has been renewed. Your next billing date is ${formattedDate}.`,
    data: {
      event: 'subscription_renewed',
      next_billing_date: nextBillingDate,
      deep_link: '/profile/subscription',
    },
    critical: false,
  });
}

/**
 * Send subscription cancellation confirmation notification
 * 
 * @param userId - User ID
 * @param accessUntil - Date when access ends
 */
export async function notifyCancellationConfirmed(
  userId: string,
  accessUntil: string
): Promise<{ success: boolean; error?: string }> {
  const formattedDate = new Date(accessUntil).toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'long',
    day: 'numeric',
  });

  return sendSubscriptionNotification({
    userId,
    title: 'Subscription Cancelled',
    body: `Your Kids Club+ subscription has been cancelled. You'll have access until ${formattedDate}, then enter a 90-day grace period where your Swap Points will be frozen.`,
    data: {
      event: 'subscription_cancelled',
      access_until: accessUntil,
      deep_link: '/profile/subscription',
    },
    critical: false,
  });
}

/**
 * Send payment failure notification (CRITICAL)
 * Always sent regardless of user preferences
 * 
 * @param userId - User ID
 * @param retryCount - Current retry count (1-3)
 */
export async function notifyPaymentFailed(
  userId: string,
  retryCount: number
): Promise<{ success: boolean; error?: string }> {
  const messages = {
    1: 'Your payment was declined. Please update your payment method to keep your subscription active.',
    2: 'Your subscription payment was declined again. Please update your payment method to avoid service interruption.',
    3: 'Final attempt failed. Your subscription will be paused soon. Please update your payment method immediately.',
  };

  const body = messages[retryCount as keyof typeof messages] || messages[1];

  return sendSubscriptionNotification({
    userId,
    title: '⚠️ Payment Failed - Action Required',
    body,
    data: {
      event: 'payment_failed',
      retry_count: retryCount,
      action_required: true,
      deep_link: '/profile/subscription',
    },
    critical: true, // Critical notification - bypasses preferences
  });
}

/**
 * FILE: p2p-kids-marketplace/src/__tests__/services/subscriptionNotifications.test.ts
 * MODULE-14 TASK NOTIF-V2-002: Unit tests for subscription notifications
 */

import { jest } from '@jest/globals';
import {
  sendSubscriptionNotification,
  notifySubscriptionRenewed,
  notifyCancellationConfirmed,
  notifyPaymentFailed,
} from '../../services/subscriptionNotifications';
import { supabase } from '../../config/supabase';

// Mock Supabase
jest.mock('../../config/supabase', () => ({
  supabase: {
    from: jest.fn(),
    functions: {
      invoke: jest.fn(),
    },
  },
}));

describe('MODULE-14 NOTIF-V2-002: Subscription Notifications', () => {
  const mockUserId = 'user-123';
  const mockNextBillingDate = '2026-05-01T00:00:00Z';

  beforeEach(() => {
    jest.clearAllMocks();
  });

  describe('sendSubscriptionNotification', () => {
    it('should send notification respecting user preferences', async () => {
      const mockPreferences = {
        push_enabled: true,
        in_app_enabled: true,
        email_enabled: false,
      };

      (supabase.from as jest.Mock).mockReturnValue({
        select: jest.fn().mockReturnValue({
          eq: jest.fn().mockReturnValue({
            eq: jest.fn().mockReturnValue({
              maybeSingle: jest.fn().mockResolvedValue({
                data: mockPreferences,
                error: null,
              }),
            }),
          }),
        }),
        insert: jest.fn().mockResolvedValue({ error: null }),
      });

      (supabase.functions.invoke as jest.Mock).mockResolvedValue({ error: null });

      const result = await sendSubscriptionNotification({
        userId: mockUserId,
        title: 'Test Notification',
        body: 'Test body',
        critical: false,
      });

      expect(result.success).toBe(true);
      expect(supabase.from).toHaveBeenCalledWith('notification_preferences');
      expect(supabase.from).toHaveBeenCalledWith('user_notifications');
      expect(supabase.functions.invoke).toHaveBeenCalledWith('send-push-notification', expect.any(Object));
    });

    it('should bypass preferences for critical notifications', async () => {
      const mockPreferences = {
        push_enabled: false,
        in_app_enabled: false,
        email_enabled: false,
      };

      (supabase.from as jest.Mock).mockReturnValue({
        select: jest.fn().mockReturnValue({
          eq: jest.fn().mockReturnValue({
            eq: jest.fn().mockReturnValue({
              maybeSingle: jest.fn().mockResolvedValue({
                data: mockPreferences,
                error: null,
              }),
            }),
          }),
        }),
        insert: jest.fn().mockResolvedValue({ error: null }),
      });

      (supabase.functions.invoke as jest.Mock).mockResolvedValue({ error: null });

      const result = await sendSubscriptionNotification({
        userId: mockUserId,
        title: 'Critical Notification',
        body: 'Critical body',
        critical: true,
      });

      expect(result.success).toBe(true);
      // Should send push even though preferences are disabled
      expect(supabase.functions.invoke).toHaveBeenCalledWith('send-push-notification', {
        body: expect.objectContaining({
          title: 'Critical Notification',
          data: expect.objectContaining({
            critical: true,
          }),
        }),
      });
    });

    it('should handle notification creation failure', async () => {
      (supabase.from as jest.Mock).mockReturnValue({
        select: jest.fn().mockReturnValue({
          eq: jest.fn().mockReturnValue({
            eq: jest.fn().mockReturnValue({
              maybeSingle: jest.fn().mockResolvedValue({
                data: null,
                error: null,
              }),
            }),
          }),
        }),
        insert: jest.fn().mockResolvedValue({
          error: { message: 'Database error' },
        }),
      });

      const result = await sendSubscriptionNotification({
        userId: mockUserId,
        title: 'Test',
        body: 'Test',
      });

      expect(result.success).toBe(false);
      expect(result.error).toBe('Database error');
