      <BadgeCelebrationModal visible={true} badge={mockBadge} onClose={mockOnClose} />
    );

    const closeButton = getByTestId('celebration-close-button');
    fireEvent.press(closeButton);

    expect(mockOnClose).toHaveBeenCalledTimes(1);
